mapper.delete:
update product
set is_delete = 1
where id = #{id}

mapper.select:
select id, user_id, name, description, price, image, status, view_count, create_time, update_time from product
status = 1
and title like concat('%',#{keyword},'%')
and category_id = #{categoryId}
and price >= #{minPrice}
and price <= #{maxPrice}
order by create_time desc

mapper.update:
update product
set view_count = view_count + 1
where id=#{id}

update product
set status=#{status}
where id = #{id}

update product
category_id = #{categoryId}, title = #{title}, price = #{price}, condition_level = #{conditionLevel}, trade_type = #{tradeType}, description = #{description}
where id = #{id}

update product
set audit_status = #{auditStatus}
where id = #{id}
